CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY AUTOINCREMENT, handle TEXT UNIQUE NOT NULL, pass_hash TEXT NOT NULL, salt TEXT NOT NULL, demo INTEGER DEFAULT 0, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, user_id INTEGER NOT NULL, expires INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS profiles (user_id INTEGER PRIMARY KEY, display TEXT, city TEXT, bio TEXT, color TEXT, items TEXT, entities TEXT, tags TEXT, archetype TEXT, tagline TEXT, updated INTEGER);
CREATE TABLE IF NOT EXISTS waves (from_id INTEGER NOT NULL, to_id INTEGER NOT NULL, created INTEGER NOT NULL, PRIMARY KEY(from_id,to_id));
CREATE TABLE IF NOT EXISTS duels (id TEXT PRIMARY KEY, creator_id INTEGER NOT NULL, target_id INTEGER NOT NULL, rounds TEXT NOT NULL, answers TEXT, score INTEGER, created INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS bridges (key TEXT PRIMARY KEY, plan TEXT NOT NULL, created INTEGER NOT NULL);
